import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("should quote 5 G for an empty item list (processing fee only)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("should quote 115 G for a single plain sword (100 G base + 10 G first insurance + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("should quote 71 G for a single plain amulet (60 G base + 6 G first insurance + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("should quote 93 G for a single plain staff (80 G base + 8 G first insurance + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it("should quote 49 G for a single plain potion (40 G base + 4 G first insurance + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 49 }] });
    });
    it("should quote 181 G for a plain sword and a plain amulet (160 G base + 16 G first insurance + 5 G fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }, { type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 181 }] });
    });
  });

  describe("quote — components and blocks", () => {
    it("should charge 25 G base per component (2 runes → 50 G base premium)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 60 }] });
    });
    it("should charge 60 G base for a block of exactly 3 alike components (3 runes)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("should charge 100 G base for 4 runes (no block — block requires exactly 3)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("should charge 175 G base for 7 runes (no block — block requires exactly 3)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 198 }] });
    });
    it("should charge 75 G base for 2 runes and 1 moonstone (no block — different types)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 88 }] });
    });
    it("should charge 120 G base for 3 runes and 3 moonstones (two separate blocks)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "moonstone" },
              { type: "moonstone" },
              { type: "moonstone" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 137 }] });
    });
  });

  describe("quote — item-specific modifiers", () => {
    it("should add 50 % of the item's base premium for a cursed item", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword", cursed: true }] }],
      });

      expect(result).toEqual({ results: [{ premium: 165 }] });
    });
    it("should add 30 % of the item's base premium for enchantment level 5", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword", enchantment: 5 }] }],
      });

      expect(result).toEqual({ results: [{ premium: 145 }] });
    });
    it("should not add the high-enchantment surcharge for enchantment level 4", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword", enchantment: 4 }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("should add both surcharges for a cursed item with enchantment level 5", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", cursed: true, enchantment: 5 }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 195 }] });
    });
    it("should apply the cursed surcharge only to the cursed item on a multi-item policy", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", cursed: true }, { type: "amulet" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 231 }] });
    });
  });

  describe("quote — policy-wide modifiers", () => {
    it("should add 10 % of the policy base premium as first insurance surcharge", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("should subtract 20 % of the policy base premium for a customer with 2 years", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 2 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 95 }] });
    });
    it("should not apply the loyalty discount for a customer with 1 year", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 1 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("should subtract 15 % of the policy base premium on each quote after the first", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword" }] },
          { op: "quote", items: [{ type: "sword" }] },
        ],
      });

      expect(result).toEqual({
        results: [{ premium: 115 }, { premium: 100 }],
      });
    });
    it("should apply the first insurance surcharge on a follow-up contract as well", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "potion" }] },
          { op: "quote", items: [{ type: "amulet" }] },
        ],
      });

      expect(result).toEqual({
        results: [{ premium: 49 }, { premium: 62 }],
      });
    });
  });

  describe("quote — rounding", () => {
    it("should round the final premium up to a whole G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 2 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "sword", cursed: true, enchantment: 5 },
              { type: "rune" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 198 }] });
    });
    it("should keep intermediate amounts as fractions and round only the final premium", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 2 },
        steps: [
          { op: "quote", items: [{ type: "rune", enchantment: 5 }] },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 35 }] });
    });
  });

  describe("quote — integration", () => {
    it("should quote 165 G for a newcomer with a cursed steel sword of enchantment 3", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              {
                type: "sword",
                material: "steel",
                enchantment: 3,
                cursed: true,
              },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 165 }] });
    });
    it("should quote 160 G for a 3-year customer's second contract with a cursed sword of enchantment 7", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 3 },
        steps: [
          { op: "quote", items: [{ type: "sword" }] },
          {
            op: "quote",
            items: [{ type: "sword", cursed: true, enchantment: 7 }],
          },
        ],
      });

      expect(result.results[1]).toEqual({ premium: 160 });
    });
  });

  describe("claim — standard reimbursement", () => {
    it("should pay 400 G for 500 G damage to a regular sword (deductible 100 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword" }] },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 500 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 400, remainingCap: 1600 });
    });
    it("should pay 100 G for 200 G damage to a rune (no enchantment or material clause)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "rune" }] },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "goblin raid",
              damages: [{ itemType: "rune", amount: 200 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 100, remainingCap: 400 });
    });
    it("should apply the 100 G deductible once per damage entry (sword 500 G + amulet 300 G → 600 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword" }, { type: "amulet" }] },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [
                { itemType: "sword", amount: 500 },
                { itemType: "amulet", amount: 300 },
              ],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 600, remainingCap: 2600 });
    });
    it("should treat two damage entries of the same item type as separate damages", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword" }, { type: "sword" }] },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [
                { itemType: "sword", amount: 500 },
                { itemType: "sword", amount: 500 },
              ],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 800, remainingCap: 3200 });
    });
  });

  describe("claim — special clauses", () => {
    it("should pay 400 G for 1000 G damage to a steel sword with enchantment 9 (50 % then deductible)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "steel", enchantment: 9 }],
          },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 1000 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 400, remainingCap: 1600 });
    });
    it("should pay 700 G for 800 G damage to a dragon-material sword with enchantment 5 (full then deductible)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "dragon", enchantment: 5 }],
          },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 800 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 700, remainingCap: 1300 });
    });
    it("should pay 400 G for 1000 G damage to a dragon-material sword with enchantment 9 (50 % rule wins)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "dragon", enchantment: 9 }],
          },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 1000 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 400, remainingCap: 1600 });
    });
    it("should pay 400 G for 1000 G damage to a dragon-material sword with exactly enchantment 8", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "sword", material: "dragon", enchantment: 8 }],
          },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 1000 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 400, remainingCap: 1600 });
    });
  });

  describe("claim — cap", () => {
    it("should report the remaining cap as twice the insurance sum minus the payout", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "sword" }] },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 700 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 600, remainingCap: 1400 });
    });
    it("should base the insurance sum on unmodified item values (sword + amulet → cap 3200 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "sword", material: "dragon", enchantment: 5 },
              { type: "amulet", enchantment: 9 },
            ],
          },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 100 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 0, remainingCap: 3200 });
    });
    it("should base the insurance sum on unmodified item values when a block discount applies (sword + 3 runes → cap 3500 G)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "sword" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
            ],
          },
          {
            op: "claim",
            policy: 0,
            incident: {
              cause: "dragon attack",
              damages: [{ itemType: "sword", amount: 100 }],
            },
          },
        ],
      });

      expect(result.results[1]).toEqual({ payout: 0, remainingCap: 3500 });
    });
    it.todo("should not raise the cap for a cursed item (cursed sword → cap 2000 G)");
    it.todo("should reduce the payout to the remaining cap when the cap is exhausted across successive claims");
  });

  describe("claim — rounding", () => {
    it.todo("should round the final payout down to a whole G");
  });

  describe("errors", () => {
    it.todo("should reject a quote containing an item of unknown type");
    it.todo("should reject a claim whose damage references an item not in the policy");
    it.todo("should reject a claim whose damage references an unknown item type");
    it.todo("should reject a claim with more damages of a type than the policy insures");
    it.todo("should reject a claim with a negative damage amount");
  });

  describe("scenario processing", () => {
    it.todo("should return one result per step in the same order as the input steps");
    it.todo("should resolve a claim's policy field to the quote step at that zero-based index");
  });
});

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const isBlock = (sameTypeItems: Item[]): boolean =>
  sameTypeItems.length === BLOCK_SIZE;

const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);

const groupByType = (items: Item[]): Item[][] =>
  Object.values(
    items.reduce<Record<string, Item[]>>(
      (groups, item) => ({
        ...groups,
        [item.type]: [...(groups[item.type] ?? []), item],
      }),
      {},
    ),
  );

const basePremiumOfGroup = (items: Item[]): number =>
  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);

const CURSED_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const UNENCHANTED = 0;

const enchantmentOf = (item: Item): number => item.enchantment ?? UNENCHANTED;

const isHighlyEnchanted = (item: Item): boolean =>
  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;

const NO_SURCHARGE_RATE = 0;

const surchargeRateOfItem = (item: Item): number =>
  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
  (isHighlyEnchanted(item)
    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
    : NO_SURCHARGE_RATE);

const surchargeOfItem = (item: Item): number =>
  basePremiumOfItem(item) * surchargeRateOfItem(item);

const sumOfItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const firstInsuranceSurcharge = (basePremium: number): number =>
  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

const roundPremiumInMHPCOsFavour = (premium: number): number =>
  Math.ceil(premium);

const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS_THRESHOLD = 2;
const NO_DISCOUNT = 0;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;

const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;

const isFollowUpContract = (previousQuoteCount: number): boolean =>
  previousQuoteCount > 0;

const followUpContractDiscount = (
  previousQuoteCount: number,
  basePremium: number,
): number =>
  isFollowUpContract(previousQuoteCount)
    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
    : NO_DISCOUNT;

const quote = (
  items: Item[],
  customer: Customer,
  previousQuoteCount: number,
): QuoteResult => {
  const basePremium = policyBasePremium(items);
  const surcharges =
    sumOfItemSurcharges(items) + firstInsuranceSurcharge(basePremium);
  const discounts =
    loyaltyDiscount(customer, basePremium) +
    followUpContractDiscount(previousQuoteCount, basePremium);
  return {
    premium: roundPremiumInMHPCOsFavour(
      PROCESSING_FEE + basePremium + surcharges - discounts,
    ),
  };
};

const DEDUCTIBLE = 100;
const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  rune: 250,
};
const CAP_FACTOR = 2;

const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
const HALF_REIMBURSEMENT_RATE = 0.5;
const FULL_REIMBURSEMENT_RATE = 1;

const damagedItem = (damage: Damage, policyItems: Item[]): Item =>
  policyItems.find((item) => item.type === damage.itemType)!;

const isDeeplyEnchanted = (item: Item): boolean =>
  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;

const reimbursementRateOfItem = (item: Item): number =>
  isDeeplyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;

const payoutOfDamage = (damage: Damage, policyItems: Item[]): number =>
  damage.amount * reimbursementRateOfItem(damagedItem(damage, policyItems)) -
  DEDUCTIBLE;

const payoutOfIncident = (incident: Incident, policyItems: Item[]): number =>
  incident.damages.reduce(
    (sum, damage) => sum + payoutOfDamage(damage, policyItems),
    0,
  );

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const capOfPolicy = (policyItems: Item[]): number =>
  CAP_FACTOR * insuranceSum(policyItems);

const claim = (incident: Incident, policyItems: Item[]): ClaimResult => {
  const payout = payoutOfIncident(incident, policyItems);
  return {
    payout,
    remainingCap: capOfPolicy(policyItems) - payout,
  };
};

const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";

const quoteSteps = (steps: Step[]): QuoteStep[] => steps.filter(isQuoteStep);

const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] =>
  quoteSteps(steps)[policy].items;

const quoteCountBefore = (steps: Step[], stepIndex: number): number =>
  quoteSteps(steps.slice(0, stepIndex)).length;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, stepIndex) =>
    isQuoteStep(step)
      ? quote(
          step.items,
          scenario.customer,
